    CHECK(ft_stream_feed(&s, bytes + split, sizeof bytes - 1 - split) == FT_OK);
    CHECK(ft_stream_finish(&s, &r) == FT_OK && r.count == 3 && r.sum == 6);
    CHECK(ft_stream_finish(&s, &r) == FT_STATE && r.sum == 6);
    CHECK(ft_stream_feed(&s, NULL, 0) == FT_STATE);
