}
const char *ft_name(FtStatus s) {
  static const char *const names[] = {"ok",      "empty",    "malformed",
                                      "range",   "capacity", "prefix",
                                      "invalid", "state",    "not-implemented"};
  return (unsigned)s < sizeof names / sizeof names[0] ? names[s] : "unknown";
}

